1	export type Item = { type: string; cursed?: boolean };
2	export type Step = { items: Item[] };
3	export type Scenario = { steps: Step[] };
4	export type Result = { premium: number };
5	export type ScenarioOutcome = { results: Result[] };
6	
7	const BASE_PREMIUMS: Record<string, number> = {
8	  sword: 100,
9	  amulet: 60,
10	  staff: 80,
11	  potion: 40,
12	  rune: 25,
13	  moonstone: 25,
14	};
15	
16	const FIRST_INSURANCE_SURCHARGE = 1.1;
17	const PROCESSING_FEE = 5;
18	
19	// Guards against binary-float artifacts (e.g. 52.800000000000004) tipping an
20	// exact value over a whole-gold boundary and inflating the premium by 1 G.
21	const FLOAT_ARTIFACT_PRECISION = 6;
22	
23	const roundUpToWholeGold = (amount: number): number =>
24	  Math.ceil(Number(amount.toFixed(FLOAT_ARTIFACT_PRECISION)));
25	
26	const CURSED_SURCHARGE = 1.5;
27	
28	const riskFactorOf = (item: Item): number => (item.cursed ? CURSED_SURCHARGE : 1);
29	
30	const basePremiumOf = (item: Item): number =>
31	  BASE_PREMIUMS[item.type] * riskFactorOf(item);
32	
33	const BUILDING_BLOCK_SIZE = 3;
34	const BUILDING_BLOCK_PREMIUM = 60;
35	
36	const areAlike = (items: Item[]): boolean =>
37	  items.every((item) => item.type === items[0].type);
38	
39	const sumOfBasePremiums = (items: Item[]): number =>
40	  items.reduce((total, item) => total + basePremiumOf(item), 0);
41	
42	// An unalike list forms no blocks at all, however many items it holds.
43	const buildingBlockCountOf = (items: Item[]): number =>
44	  areAlike(items) ? Math.floor(items.length / BUILDING_BLOCK_SIZE) : 0;
45	
46	// Alike items group into building blocks priced below the sum of their members'
47	// base premiums; everything left over prices at base.
48	const blockPricedTotalOf = (items: Item[]): number => {
49	  const blocks = buildingBlockCountOf(items);
50	  const looseItems = items.slice(blocks * BUILDING_BLOCK_SIZE);
51	
52	  return blocks * BUILDING_BLOCK_PREMIUM + sumOfBasePremiums(looseItems);
53	};
54	
55	const premiumFor = (step: Step): number =>
56	  roundUpToWholeGold(blockPricedTotalOf(step.items) * FIRST_INSURANCE_SURCHARGE) +
57	  PROCESSING_FEE;
58	
59	export const runScenario = (scenario: Scenario): ScenarioOutcome => ({
60	  results: [{ premium: premiumFor(scenario.steps[0]) }],
61	});
